-- currtime_income_v3 全量建表（含 HID0123/HID0124）
-- 院区：HID0101/0103/0117/0120/0122/0123/0124
-- hid0123 库两院区：ct_loc.ctloc_hospital_dr 2→HID0123，12→HID0124
-- 已有 MV 需 DROP 后重建，异步 MV 不支持直接改 AS 定义

CREATE MATERIALIZED VIEW `indicators`.`currtime_income_v3` (`hosp_code`, `abdate`, `paadmtype`, `tectype`, `ordloc_code`, `ordloc`, `recloc_code`, `recloc`, `patloccode`, `patloc`, `patwardcode`, `patward`, `totalfee`, `lastupdatedttm`)
COMMENT "实时收入"
DISTRIBUTED BY HASH(`hosp_code`)
REFRESH ASYNC EVERY(INTERVAL 180 SECOND)
PROPERTIES (
"replicated_storage" = "true",
"replication_num" = "3",
"storage_medium" = "HDD"
)
AS SELECT 'HID0101' AS `hosp_code`, `hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_createdate` AS `abdate`, `hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_type` AS `paadmtype`, `hid0101_cache_his_dhcapp_sqluser`.`tarec`.`tartec_desc` AS `tectype`, `hid0101_cache_his_dhcapp_sqluser`.`ctloc`.`ctloc_code` AS `ordloc_code`, `hid0101_cache_his_dhcapp_sqluser`.`ctloc`.`ctloc_desc` AS `ordloc`, `hid0101_cache_his_dhcapp_sqluser`.`ctlocjs`.`ctloc_code` AS `recloc_code`, `hid0101_cache_his_dhcapp_sqluser`.`ctlocjs`.`ctloc_desc` AS `recloc`, `hid0101_cache_his_dhcapp_sqluser`.`ctlocjzks`.`ctloc_code` AS `patloccode`, `hid0101_cache_his_dhcapp_sqluser`.`ctlocjzks`.`ctloc_desc` AS `patloc`, `hid0101_cache_his_dhcapp_sqluser`.`zyward`.`ward_code` AS `patwardcode`, `hid0101_cache_his_dhcapp_sqluser`.`zyward`.`ward_desc` AS `patward`, CAST((sum(CASE WHEN ((abs(CAST(`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_totalamount` AS DECIMAL64(18,4)))) > (abs((CAST(`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_totalamount` AS DECIMAL64(18,4))) - (coalesce(CAST(`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_discamount` AS DECIMAL64(18,4)), 0))))) THEN (CAST(`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_totalamount` AS DECIMAL64(18,4))) ELSE ((CAST(`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_totalamount` AS DECIMAL64(18,4))) - (coalesce(CAST(`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_discamount` AS DECIMAL64(18,4)), 0))) END)) AS DOUBLE) AS `totalfee`, current_timestamp() AS `lastupdatedttm`
FROM `hid0101_cache_his_dhcapp_sqluser`.`dhc_patbilldetails` AS `billdet` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`dhc_patbillorder` AS `pbo` ON `hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_pbo_parref` = `hid0101_cache_his_dhcapp_sqluser`.`pbo`.`pbo_rowid` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`dhc_patientbill` AS `bill` ON `hid0101_cache_his_dhcapp_sqluser`.`bill`.`pb_rowid` = `hid0101_cache_his_dhcapp_sqluser`.`pbo`.`pbo_pb_parref` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`pa_adm` AS `adm` ON `hid0101_cache_his_dhcapp_sqluser`.`bill`.`pb_adm_dr` = `hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_rowid` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`dhc_taritem` AS `taritem` ON `hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_tari_dr` = `hid0101_cache_his_dhcapp_sqluser`.`taritem`.`tari_rowid` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`dhc_taremccate` AS `taremc` ON `hid0101_cache_his_dhcapp_sqluser`.`taritem`.`tari_emccate` = `hid0101_cache_his_dhcapp_sqluser`.`taremc`.`tarec_rowid` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`dhc_tarec` AS `tarec` ON `hid0101_cache_his_dhcapp_sqluser`.`tarec`.`tartec_rowid` = `hid0101_cache_his_dhcapp_sqluser`.`taremc`.`tarec_tartec_dr` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`oe_orditem` AS `oeori` ON `hid0101_cache_his_dhcapp_sqluser`.`oeori`.`oeori_rowid` = `hid0101_cache_his_dhcapp_sqluser`.`pbo`.`pbo_oeori_dr` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`ct_loc` AS `ctloc` ON `hid0101_cache_his_dhcapp_sqluser`.`oeori`.`oeori_orddept_dr` = `hid0101_cache_his_dhcapp_sqluser`.`ctloc`.`ctloc_rowid` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`ct_loc` AS `ctlocjs` ON `hid0101_cache_his_dhcapp_sqluser`.`oeori`.`oeori_recdep_dr` = `hid0101_cache_his_dhcapp_sqluser`.`ctlocjs`.`ctloc_rowid` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`ct_loc` AS `ctlocjzks` ON `hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_depcode_dr` = `hid0101_cache_his_dhc