WHERE ((`hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_rowid` NOT IN (((((SELECT `indicators`.`tmp_exclude_ids`.`id`
FROM `indicators`.`tmp_exclude_ids`)))))) AND (((`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_createdate` = (CAST((current_date()) AS VARCHAR))) AND (`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`isdeleted` = '0')) AND ((length(`hid0101_cache_his_dhcapp_sqluser`.`billdet`.`pbd_totalamount`)) < 12))) AND (((`hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_type` = 'I') OR ((`hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_type` = 'O') AND (`hid0101_cache_his_dhcapp_sqluser`.`bill`.`pb_payedflag` = 'P'))) OR ((`hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_type` = 'E') AND ((`hid0101_cache_his_dhcapp_sqluser`.`bill`.`pb_payedflag` = 'P') OR (`hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_currentward_dr` IS NOT NULL))))
