,4))) - (coalesce(CAST(`hid0103_cache_his_dhcapp_sqluser`.`billdet`.`pbd_discamount` AS DECIMAL64(18,4)), 0))) END)) AS DOUBLE) AS `totalfee`, current_timestamp() AS `lastupdatedttm`
